      radius: 25, blur: 30, minOpacity: 0.42,
      gradient: { 0.05: "rgba(90,35,0,0)", 0.22: "#c2650a", 0.42: "#f5a623", 0.62: "#ff7a1a", 0.82: "#ff3b3b", 1.0: "#fff6e0" }
